import {
  ChangeDetectionStrategy,
  Component,
  OnInit,
  ChangeDetectorRef,
  Inject,
  Optional,
  ViewChild,
  ElementRef
} from '@angular/core';
import { HorseracingAboutService } from '../../services/horseracing-about.service';
import { finalize, skip, take, takeUntil } from 'rxjs/operators';
import { HowToBetTypesGuide } from '../../models/howto-bettypes-guide.model';
import { I18nService } from '@honoregaming/i18n';
import {
  AsyncTrigger,
  Async,
  BetTypeConfiguration,
  horseRaceBetTypesConfiguration,
  DestroySubject
} from '@honoregaming/core';
import { forkJoin, merge } from 'rxjs';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Media, MediaService } from '@honoregaming/ui';
import { ActivatedRoute } from '@angular/router';
import { HowToBetTypeCustomIcon } from '../../models/howto-bettypecustomicon';

@Component({
  selector: 'hg-horseracing-about-bettypes-guide-content',
  templateUrl: './bettypes-guide-content.component.html',
  styleUrls: ['./bettypes-guide-content.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetTypesGuideContentComponent extends DestroySubject implements OnInit {
  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  currentBetType: string;
  showFormulaContent = false;
  showMoreContent = false;

  content: HowToBetTypesGuide;
  loadingContent = false;
  error: string;
  operatorName: string;
  index = 1;
  tabId: number;
  next = 1;
  start = 0;
  limit = 9;
  tabLimitMc: number;
  tabLimitMs: number;
  tabLimit: number;
  navigation = true;
  hasMc = false;
  hasMs = false;
  countBetTypesMc = 0;
  countBetTypesMs = 0;

  betTypesConfigurationMc: { [key: number]: BetTypeConfiguration } = {};
  betTypesConfigurationMs: { [key: number]: BetTypeConfiguration } = {};

  @ViewChild('jumpToSection') jumpToSection: ElementRef;

  constructor(
    private horseracingAboutService: HorseracingAboutService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Optional() private mediaService: MediaService,
    private activatedRoute: ActivatedRoute,
    private i18nService: I18nService,
    private cdRef: ChangeDetectorRef
  ) {
    super();
  }

  queryParams: {
    nav: number;
  } = { nav: 1 };

  @Async()
  ngOnInit() {
    this.index = +this.activatedRoute.snapshot.queryParams['nav'];
    this.activatedRoute.queryParams.subscribe(params => {
      this.tabId = +params['id'];
    });

    this.loadingContent = true;
    this.operatorName = this.operatorConfiguration.name;

    const horseRacingBetTypes = this.horseracingAboutService.getHorseRacingBetTypesWithIcon();
    const horseRacingHowToContent = this.horseracingAboutService.getHorseRacingHowToContent();

    forkJoin([horseRacingBetTypes, horseRacingHowToContent])
      .pipe(
        takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))),
        finalize(() => {
          this.loadingContent = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        ([horseRacingBetTypes, c]) => {
          this.generateHorseRacingBetTypesConfiguration(horseRacingBetTypes);
          this.content = c.betTypesGuideContents;
          this.onTabClick(this.index);
        },
        error => (this.error = error)
      );
  }

  generateHorseRacingBetTypesConfiguration(horseRacingBetTypesIds: HowToBetTypeCustomIcon[]) {
    horseRacingBetTypesIds.forEach(bet => {
      if (bet.id < 1000) {
        this.betTypesConfigurationMc[bet.id] = horseRaceBetTypesConfiguration[bet.id];
        this.countBetTypesMc++;
        this.hasMc = true;
        this.index = 1;
        this.tabLimitMc = Math.ceil(this.countBetTypesMc / this.limit);

        this.betTypesConfigurationMc[bet.id].iconUrl = bet.iconUrl;
      } else {
        this.betTypesConfigurationMs[bet.id] = horseRaceBetTypesConfiguration[bet.id];
        this.countBetTypesMs++;
        this.index = 2;
        this.tabLimitMs = Math.ceil(this.countBetTypesMs / this.limit);
        this.hasMs = true;

        this.betTypesConfigurationMs[bet.id].iconUrl = bet.iconUrl;
      }
    });
  }

  onTabClick(index: number) {
    this.index = index;
    this.next = 1;
    this.start = 0;
    this.limit = 9;

    this.mediaService.media$.pipe(take(1)).subscribe(x => {
      if (x >= Media.md) {
        this.start = 0;
        this.limit = 5000;
        this.navigation = false;
      }
    });

    switch (index) {
      case 1:
        this.selectBetType(Object.keys(this.betTypesConfigurationMc).sort((a, b) => Number(a) - Number(b))[0]);
        break;
      case 2:
        this.selectBetType(Object.keys(this.betTypesConfigurationMs).sort((a, b) => Number(a) - Number(b))[0]);
        break;
      case 3:
        this.selectFormula();
        break;
      case 4:
        this.selectMore();
        break;
      default:
        this.selectBetType('1');
        break;
    }
  }

  nextTab() {
    if (this.index === 1) {
      this.tabLimit = this.tabLimitMc;
      if (this.next != this.tabLimitMc) {
        this.next += 1;
        this.start += 9;
        this.limit += 9;
      }
    }

    if (this.index === 2) {
      this.tabLimit = this.tabLimitMs;
      if (this.next != this.tabLimitMs) {
        this.next += 1;
        this.start += 9;
        this.limit += 9;
      }
    }
  }

  previousTab() {
    if (this.next != 1) {
      this.next = this.next -= 1;
      this.start -= 9;
      this.limit -= 9;
    }
  }

  selectBetType(betType: string, elementId?: string) {
    this.currentBetType = betType;
    this.showFormulaContent = false;
    this.showMoreContent = false;

    this.mediaService?.media$.subscribe(x => {
      if (x <= Media.md && elementId) {
        if (this.jumpToSection?.nativeElement) {
          this.jumpToSection.nativeElement.scrollIntoView({ behavior: 'smooth' });
        }
      }
    });
  }

  selectFormula() {
    this.currentBetType = null;
    this.showFormulaContent = true;
    this.showMoreContent = false;
  }

  selectMore() {
    this.currentBetType = null;
    this.showFormulaContent = false;
    this.showMoreContent = true;
  }

  descOrder(a, b) {
    if (a.key < b.key) {
      return b.key;
    }
    return a.key;
  }
}
