import { ChangeDetectionStrategy, Component, OnInit, ChangeDetectorRef } from '@angular/core';
import { HorseracingAboutService } from '../../services/horseracing-about.service';
import { finalize, skip, takeUntil } from 'rxjs/operators';
import { HowToBetContent } from '../../models/howto-betcontent.model';
import { AsyncTrigger, Async, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { merge } from 'rxjs';

@Component({
  selector: 'hg-horseracing-about-howto-bet-content',
  templateUrl: './howto-bet-content.component.html',
  styleUrls: ['./howto-bet-content.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HowToBetContentComponent extends DestroySubject implements OnInit {
  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  content: HowToBetContent[];
  loadingContent = false;
  error: string;

  constructor(
    private i18nService: I18nService,
    private horseracingAboutService: HorseracingAboutService,
    private cdRef: ChangeDetectorRef
  ) {
    super();
  }

  @Async()
  ngOnInit() {
    this.loadingContent = true;
    this.horseracingAboutService
      .getHorseRacingHowToContent()
      .pipe(
        takeUntil(merge(this.destroy$, this.i18nService.languageChanged$.pipe(skip(1)))),
        finalize(() => {
          this.loadingContent = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        c => {
          this.content = c.howToBetContents;
        },
        error => (this.error = error)
      );
  }
}
