import { NgModule, ModuleWithProviders } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HgHorseracingAboutRoutingModule } from './hg-horseracing-about-routing.module';
import { HomeContentComponent } from './containers/home/home.component';
import { RaceTypesContentComponent } from './containers/racetypes-content/racetypes-content.component';
import { HowToBetContentComponent } from './containers/howto-bet-content/howto-bet-content.component';
import { BetTypesGuideContentComponent } from './containers/bettypes-guide-content/bettypes-guide-content.component';
import { HgUiModule } from '@honoregaming/ui';
import { HgI18nModule } from '@honoregaming/i18n';
import { HorseRacingAboutHeaderComponent } from './components/about-header/about-header.component';
import { HorseracingAboutContentComponent } from './components/about-content/about-content.component';
import { BetTypeGuideComponent } from './components/bettype-guide/bettype-guide.component';
import { HorseRacingCouponContentComponent } from './containers/coupon-content/horseracing-coupon-content.component';

@NgModule({
  imports: [CommonModule, HgHorseracingAboutRoutingModule, HgUiModule, HgI18nModule],
  declarations: [
    HomeContentComponent,
    RaceTypesContentComponent,
    HowToBetContentComponent,
    BetTypesGuideContentComponent,
    HorseRacingAboutHeaderComponent,
    HorseracingAboutContentComponent,
    BetTypeGuideComponent,
    HorseRacingCouponContentComponent
  ],
  exports: [BetTypeGuideComponent]
})
export class HgHorseracingAboutModule {
  static forRoot(): ModuleWithProviders<HgHorseracingAboutModule> {
    return {
      ngModule: HgHorseracingAboutModule,
      providers: []
    };
  }
}
