import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';
import { HowToBetTypeContent } from '../../models/howto-bettypecontent.model';
import { horseRaceBetTypesConfiguration, BetTypeConfiguration } from '@honoregaming/core';

@Component({
  selector: 'hg-horseracing-about-bettype-guide',
  templateUrl: './bettype-guide.component.html',
  styleUrls: ['./bettype-guide.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetTypeGuideComponent implements OnChanges {
  @Input()
  betType: string;

  @Input()
  content: HowToBetTypeContent;

  betTypeConfiguration: BetTypeConfiguration;
  betTypeBackgroundColor: string;

  ngOnChanges(): void {
    this.betTypeConfiguration = horseRaceBetTypesConfiguration[this.betType];
    this.betTypeBackgroundColor = this.betTypeConfiguration.color.concat('20');
  }
}
