import { Inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { HowToContent } from '../models/howto-content.model';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Cacheable, CacheableVaryByKey } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { HowToBetTypeCustomIcon } from '../models/howto-bettypecustomicon';

@Injectable({ providedIn: 'root' })
export class HorseracingAboutService {
  constructor(
    private httpClient: HttpClient,
    private i18nService: I18nService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {
    this.i18nService.languageChanged$.subscribe(lang => (this.userLanguage = lang));
  }

  @CacheableVaryByKey()
  userLanguage: string;

  @Cacheable()
  getHorseRacingHowToContent(): Observable<HowToContent> {
    return this.httpClient.get<any>(
      `${globalConfiguration.staticAssetsPath}${this.operatorConfiguration.commercialCode}/horseracing-how-to/${this.i18nService.currentLanguageCode}.json`
    );
  }

  @Cacheable()
  getHorseRacingBetTypesWithIcon(): Observable<HowToBetTypeCustomIcon[]> {
    return this.httpClient.get<HowToBetTypeCustomIcon[]>(
      `${globalConfiguration.apiEventsBaseUrl}bet-types/horse-racing/with-icons`
    );
  }
}
