import { RouterModule, Routes } from '@angular/router';
import { NgModule } from '@angular/core';
import { HomeContentComponent } from './containers/home/home.component';
import { RaceTypesContentComponent } from './containers/racetypes-content/racetypes-content.component';
import { HowToBetContentComponent } from './containers/howto-bet-content/howto-bet-content.component';
import { BetTypesGuideContentComponent } from './containers/bettypes-guide-content/bettypes-guide-content.component';
import { HorseRacingCouponContentComponent } from './containers/coupon-content/horseracing-coupon-content.component';

const routes: Routes = [
  {
    path: '',
    children: [
      { path: '', component: HomeContentComponent },
      { path: 'race-types', component: RaceTypesContentComponent },
      { path: 'howto-bet', component: HowToBetContentComponent },
      { path: 'bettypes-guide', component: BetTypesGuideContentComponent },
      { path: 'coupons', component: HorseRacingCouponContentComponent }
    ],
    data: { 'sidebar-content': 'none' }
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgHorseracingAboutRoutingModule {}
